"""Service mesh circuit breaker with half-open trial progression."""

from circuit_state import CircuitState


class MeshCircuitBreaker:
    def __init__(self, failure_threshold: int = 3, success_threshold: int = 3, cooldown_sec: float = 5.0):
        self.failure_threshold = failure_threshold
        self.success_threshold = success_threshold
        self.cooldown_sec = cooldown_sec
        self.state = CircuitState.CLOSED
        self.consecutive_failures = 0
        self.consecutive_successes = 0
        self.tripped_at: float = 0.0

    def allow_request(self, now: float) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if now - self.tripped_at >= self.cooldown_sec:
                self.state = CircuitState.HALF_OPEN
                self.consecutive_successes = 0
                return True
            return False
        return True  # HALF_OPEN allows probe requests

    def record_result(self, success: bool, now: float) -> None:
        if not success:
            self.consecutive_failures += 1
            self.consecutive_successes = 0
            self.state = CircuitState.OPEN
            self.tripped_at = now
        else:
            if self.state == CircuitState.HALF_OPEN:
                # BUG: Resets consecutive_successes to 0 instead of incrementing toward success_threshold!
                # Circuit remains stuck in HALF_OPEN oscillating forever.
                self.consecutive_successes = 0
                if self.consecutive_successes >= self.success_threshold:
                    self.state = CircuitState.CLOSED
            elif self.state == CircuitState.CLOSED:
                self.consecutive_failures = 0

repo_files.mesh_proxy.py:
"""Mesh proxy wrapping upstream calls with circuit breaker."""

from typing import Callable
from circuit_breaker import MeshCircuitBreaker


class MeshProxy:
    def __init__(self, breaker: MeshCircuitBreaker):
        self.breaker = breaker

    def send(self, now: float, fn: Callable[[], bool]) -> bool:
        if not self.breaker.allow_request(now):
            return False
        res = fn()
        self.breaker.record_result(res, now)
        return res

